  `eft_reference` varchar(100) DEFAULT NULL,
  `is_reconciled` tinyint(4) NOT NULL DEFAULT 0,
  `reconciled_at` datetime DEFAULT NULL,
  `source_file` varchar(500) DEFAULT NULL,
